function mbPrepNative() {
  try {
    if (!document.getElementById("mb-native-css")) {
      const st = document.createElement("style")
      st.id = "mb-native-css"
      st.textContent = MB_NATIVE_CSS
      document.head.appendChild(st)
    }
    if (!document.getElementById("boot")) {
      const bt = document.createElement("div")
      bt.id = "boot"
      bt.innerHTML = MB_BOOT_HTML
      ;(document.body || document.documentElement).appendChild(bt)
    }
    const showBootErr = (m: any) => {
      const bb = document.getElementById("boot")
      if (!bb) return
      bb.style.flexDirection = "column"
      bb.style.padding = "20px"
      bb.style.textAlign = "center"
      bb.style.color = "#f87171"
      bb.innerHTML = "MeBook load hoy nai<br><small style='color:#94a3b8;font-weight:500'>" + String(m).replace(/</g, "&lt;") + "</small>"
    }
    window.addEventListener("error", (e: any) => showBootErr(e.message || "Script error"))
    window.addEventListener("unhandledrejection", (e: any) => showBootErr((e.reason && e.reason.message) || e.reason))
  } catch {}
}

function mbNativeBootstrap() {
/* MeBook native (Capacitor) bootstrap - does nothing on normal websites */
(function(){
  try{
    var C=window.Capacitor;
    var ua=navigator.userAgent||"";
    var native=!!(C&&((C.isNativePlatform&&C.isNativePlatform())||(C.getPlatform&&C.getPlatform()!=="web")))||/MeBookApp/i.test(ua)||(/Android/i.test(ua)&&/; wv\)/.test(ua))||/[?&]mbnative=1/.test(location.search);
    C=window.Capacitor||{};
    if(!native)return;
    mbPrepNative();
    window.__mbNative=true;
    window.__mbBootDone=function(){
      var b=document.getElementById("boot"); if(!b)return;
      b.style.opacity="0"; setTimeout(function(){var x=document.getElementById("boot"); if(x&&x.parentNode)x.parentNode.removeChild(x);},280);
    };
    setTimeout(function(){window.__mbBootDone&&window.__mbBootDone();},12000);
    var de=document.documentElement;
    de.classList.add("mb-native");
    var P=C.Plugins||{};
    function sb(){return P.StatusBar;}
    function plug(n){
      try{
        var c=window.Capacitor||C;
        var pl=c.Plugins||P||{};
        if(pl[n])return pl[n];
        if(c.registerPlugin)return c.registerPlugin(n);
      }catch(e){}
      return null;
    }
    function safe(fn){ try{ var r=fn(); if(r&&r.catch)r.catch(function(){}); }catch(e){} }
    window.__mbSyncStatusBar=function(dark){
      window.__mbSBDark=dark;
      var apply=function(){
        var d=window.__mbSBDark;
        var st=d?"DARK":"LIGHT"; /* DARK = white icons (dark bg) · LIGHT = black icons (light bg) */
        safe(function(){
          var tc=document.querySelector('meta[name="theme-color"]');
          if(tc)tc.setAttribute("content",d?"#000000":"#ffffff");
        });
        /* Custom Android bridge (optional): MeBookNative.setStatusBarDark(true=dark theme/white icons, false=light theme/black icons) */
        var NB=window.MeBookNative;
        var hasBridge=!!(NB&&NB.setStatusBarDark);
        if(hasBridge)safe(function(){return NB.setStatusBarDark(!!d);});
        /* Fallback when icon colour cannot be controlled: soft dark scrim behind the status bar in light mode so white icons stay visible */
        de.classList.toggle("mb-sb-scrim",!d&&!hasBridge);
        var SB=plug("SystemBars");   /* Capacitor 7+ (edge-to-edge) */
        if(SB&&SB.setStyle){ safe(function(){return SB.setStyle({style:st});}); safe(function(){return SB.setStyle({style:st,bar:"StatusBar"});}); }
        var S=plug("StatusBar");     /* older Capacitor */
        if(S){
          if(S.setOverlaysWebView)safe(function(){return S.setOverlaysWebView({overlay:true});});
          if(S.setBackgroundColor)safe(function(){return S.setBackgroundColor({color:d?"#000000":"#ffffff"});});
          if(S.setStyle)safe(function(){return S.setStyle({style:st});});
        }
      };
      apply();
      [150,500,1200,3000,6000].forEach(function(t){setTimeout(apply,t);});
    };
    document.addEventListener("visibilitychange",function(){
      if(!document.hidden&&window.__mbSBDark!==undefined&&window.__mbSyncStatusBar)window.__mbSyncStatusBar(window.__mbSBDark);
    });
    window.__mbSyncStatusBar(true);
    /* fallback: if no inset value arrives from the shell, assume a standard 32px status bar */
    function chk(){
      try{
        var pr=document.createElement("div");
        pr.style.cssText="position:fixed;top:0;left:0;width:1px;visibility:hidden;pointer-events:none;height:var(--sat,0px)";
        document.body.appendChild(pr);
        var h=pr.getBoundingClientRect().height;
        document.body.removeChild(pr);
        if(!h||h<8){ de.style.setProperty("--mb-sat-fallback","32px"); }
      }catch(e){}
    }
    window.addEventListener("load",function(){setTimeout(chk,700);setTimeout(chk,2500);});
    try{ P.SplashScreen&&P.SplashScreen.hide&&P.SplashScreen.hide(); }catch(e){}
    try{
      P.App&&P.App.addListener&&P.App.addListener("backButton",function(){
        var h=window.__mebookBack, ok=false;
        try{ ok=h?!!h():false; }catch(e){}
        if(!ok){ try{ P.App.exitApp(); }catch(e){} }
      });
    }catch(e){}
    /* keep focused inputs visible above the keyboard */
    document.addEventListener("focusin",function(ev){
      var t=ev.target;
      if(!t||!/^(INPUT|TEXTAREA)$/.test(t.tagName)&&!t.isContentEditable)return;
      [250,500].forEach(function(d){setTimeout(function(){
        try{t.scrollIntoView({block:"center",behavior:"smooth"});}catch(e){}
      },d);});
    });
  }catch(e){}
})();
}

if (typeof window !== "undefined") {
  try {
    if (!document.getElementById("mb-base-css")) {
      const bs = document.createElement("style")
      bs.id = "mb-base-css"
      bs.textContent = MB_BASE_CSS
      document.head.appendChild(bs)
    }
    const vp = document.querySelector('meta[name="viewport"]')
    if (vp && !/viewport-fit/.test(vp.getAttribute("content") || "")) {
      vp.setAttribute("content", (vp.getAttribute("content") || "width=device-width, initial-scale=1") + ", viewport-fit=cover")
    }
    mbNativeBootstrap()
  } catch {}
}



