    if(c.liveAt) st = 'ended'; else if(/no answer/i.test(label)) st = 'missed'; else if(/declined/i.test(label)) st = 'declined'; else if(/busy/i.test(label)) st = 'busy'; else if(label === 'Call ended') st = 'cancelled'; else return;
