function MsgPressMenu(props) {
  const h = React.createElement;
  const openedAt = useRef(Date.now());
  const r = props.rect;
  const vw = window.innerWidth, vh = window.innerHeight;
  const barH = 56, gap = 10, itemH = 46;
  const cardH = props.items.length * itemH;
  const maxPrev = Math.max(60, vh - barH - cardH - gap * 2 - 90);
  const prevH = Math.min(r.height, maxPrev);
  const total = barH + gap + prevH + gap + cardH;
  let top = r.top - barH - gap;
  if (top < 56) top = 56;
  if (top + total > vh - 12) top = Math.max(8, vh - 12 - total);
  const side = props.mine ? { right: Math.max(10, vw - r.right) } : { left: Math.max(10, r.left) };
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") props.onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  const tryClose = () => {
    if (Date.now() - openedAt.current > 350) props.onClose();
  };
  const cls = props.mine ? "me" : "them";
  return h(
    "div",
    { className: "mpm-bg", onClick: tryClose, onContextMenu: (e) => e.preventDefault() },
    h(
      "div",
      Object.assign({ className: "mpm-col " + cls, style: Object.assign({ top, maxWidth: vw - 20 }, side), onClick: (e) => e.stopPropagation() }),
      h("div", { className: "mpm-bar" }, CHAT_REACTIONS.map((x, i) => h("button", { key: x.key, type: "button", className: props.myReaction === x.key ? "on" : "", style: { "--i": i }, onClick: () => props.onReact(x.key, x.emoji) }, x.emoji))),
      h("div", { className: "mpm-prev", style: Object.assign({ maxHeight: prevH }, props.themeStyle || {}) }, h("div", { className: "mechat-bubble " + cls }, props.preview)),
      h("div", { className: "mpm-card" }, props.items.map((it, i) => h("button", { key: i, className: "mpm-item" + (it.danger ? " danger" : ""), onClick: () => {
        props.onClose();
        it.onClick();
      } }, it.icon, h("span", null, it.label))))
    )
  );
}

type SheetItem = {
  label: string
  icon: React.ReactNode
  danger?: boolean
  onClick: () => void
}

function ActionSheet({ items, onClose }: { items: SheetItem[]; onClose: () => void }) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose()
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onClose])

  return (
    <div className="mb-sheet-backdrop" onClick={onClose}>
      <div className="mb-sheet" onClick={(e) => e.stopPropagation()}>
        <div className="mb-sheet-grip" />
        {items.map((it, i) => (
          <button
            key={i}
            className={`mb-sheet-item${it.danger ? " danger" : ""}`}
            onClick={() => {
              onClose()
              it.onClick()
            }}
          >
            {it.icon}
            {it.label}
          </button>
        ))}
      </div>
    </div>
  )
}

