function mcThemeStyle(t) {
  if (!t || t.id === "default" && !t.img) return void 0;
  if (t.img) return { background: "center / cover no-repeat url(" + t.img + ")" };
  const th = MC_THEMES.find((x) => x.id === t.id);
  return th && th.bg ? { background: th.bg } : void 0;
}

function mcVisibleMsgs(msgs, prefs, id) {
  const ms = prefs && prefs.disap && prefs.disap[id];
  if (!ms) return msgs;
  const now = Date.now();
  return msgs.filter((m) => {
    const t = m.at && (m.at.toMillis ? m.at.toMillis() : m.at.seconds ? m.at.seconds * 1e3 : 0);
    return !t || now - t < ms;
  });
}

function mcBurst(emoji) {
  try {
    const box = document.createElement("div");
    box.style.cssText = "position:fixed;inset:0;pointer-events:none;z-index:99999;overflow:hidden";
    for (let i = 0; i < 26; i++) {
      const s = document.createElement("span");
      s.textContent = emoji;
      s.style.cssText = "position:absolute;left:" + Math.random() * 100 + "%;bottom:-40px;font-size:" + (18 + Math.random() * 24) + "px;animation:mcFxUp " + (1.6 + Math.random() * 1.6) + "s ease-out forwards;animation-delay:" + Math.random() * 0.5 + "s";
      box.appendChild(s);
    }
    document.body.appendChild(box);
    setTimeout(() => box.remove(), 3800);
  } catch (e) {
  }
}

function mcWordFx(text, prefs, chatId) {
  if (!text) return;
  const t = String(text).toLowerCase();
  for (const f of MC_WFX) {
    if (prefs && prefs.wfxOff && prefs.wfxOff[chatId + ":" + f.k]) continue;
    if (f.words.some((w) => t.includes(w))) {
      mcBurst(f.emoji);
      return;
    }
  }
}

