  const [val, setVal] = React.useState("");
  const photoRef = React.useRef(null);
  const themeRef = React.useRef(null);
  const nickMap = prefs.nick && prefs.nick[id] || {};
  const flag = (k) => !!(prefs[k] && prefs[k][id]);
  const toggleFlag = (k) => props.updatePrefs((p) => {
    p[k] = p[k] || {};
    if (p[k][id]) delete p[k][id];
    else p[k][id] = 1;
    return p;
  });
  const userOf = (uid) => uid === me.uid ? me : !isGroup && uid === chat.otherId ? Object.assign({ uid }, chat.other) : props.allUsers.find((u) => u.uid === uid) || { uid, name: "User" };
  const dispName = (uid) => nickMap[uid] || (uid === me.uid ? "You" : userOf(uid).name || "User");
  const name = isGroup ? chat.other.name : nickMap[chat.otherId] || chat.other.name;
  const avatar = isGroup ? chat.other.photoURL ? chat.other.photoURL : props.avatarOf({ name: chat.other.name }) : props.avatarOf(chat.other);
  const memberIds = isGroup ? (chat.members || []).slice() : [me.uid, chat.otherId];
  const members = memberIds.map((u) => userOf(u));
  const muted = !!(prefs.muted && prefs.muted[id]);
  const msgs = props.messages || [];
  const images = msgs.filter((m) => m.type === "image" && m.imageUrl).slice().reverse();
  const links = [];
  msgs.forEach((m) => {
    if (m.text) (String(m.text).match(/https?:\/\/[^\s]+/g) || []).forEach((u) => links.push({ u, m }));
  });
  const pinIds = prefs.pinMsgs && prefs.pinMsgs[id] || [];
  const pinned = msgs.filter((m) => pinIds.includes(m.id));
